INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(211645, 12299, 772, '<td valign="top">Beautiful shot.. I love the exposure on this one.. the children in the frame really make this shot pop... great work :) = 10 - setzler</td>', 'Beautiful shot.. I love the exposure on this one.. the children in the frame really make this shot pop... great work :) = 10 - setzler', '2003-02-10 00:04:53.000000', NULL, 1),
(211647, 12143, 772, '<td valign="top">Good use of perspective, but the subject matter of the shot is fairly bland overall... It''s not grabbing my attention... - setzler</td>', 'Good use of perspective, but the subject matter of the shot is fairly bland overall... It''s not grabbing my attention... - setzler', '2003-02-10 00:05:38.000000', NULL, 1),
(211649, 12130, 772, '<td valign="top">excellent extreme angle perspective shot... excellent exposure as well... the sun and the minor lens flare make this shot quite interesting :) - setzler</td>', 'excellent extreme angle perspective shot... excellent exposure as well... the sun and the minor lens flare make this shot quite interesting :) - setzler', '2003-02-10 00:06:42.000000', NULL, 1),
(211658, 12200, 772, '<td valign="top">very nice exposure in the sky color here... excellent use of perspective as well.. - setzler</td>', 'very nice exposure in the sky color here... excellent use of perspective as well.. - setzler', '2003-02-10 00:13:02.000000', NULL, 1),
(211660, 12299, 4493, '<td valign="top">Some may not like the grainyness. I think it adds great character to the shot. Nice work.</td>', 'Some may not like the grainyness. I think it adds great character to the shot. Nice work.', '2003-02-10 00:13:53.000000', NULL, 1),
(211665, 12149, 4493, '<td valign="top">Excellent detail. I like that you thought outside the large box and went small for this one. Your white balance is perfect! Nice shot.</td>', 'Excellent detail. I like that you thought outside the large box and went small for this one. Your white balance is perfect! Nice shot.', '2003-02-10 00:17:02.000000', NULL, 1),
(211666, 12280, 772, '<td valign="top">I like tue subdued color in this shot... very nice use of patterns and randomness... nice work :) - setzler</td>', 'I like tue subdued color in this shot... very nice use of patterns and randomness... nice work :) - setzler', '2003-02-10 00:17:28.000000', NULL, 1),
(211669, 12290, 772, '<td valign="top">nice work.. the diagonals here really set this photo in motion.. the deep blue against the desaturated brickwork looks nice :) - setzler</td>', 'nice work.. the diagonals here really set this photo in motion.. the deep blue against the desaturated brickwork looks nice :) - setzler', '2003-02-10 00:20:01.000000', NULL, 1),
(211676, 12174, 6202, '<td valign="top">very nice, I like the white on white effect, almost an erry decadence to it</td>', 'very nice, I like the white on white effect, almost an erry decadence to it', '2003-02-10 00:27:06.000000', NULL, 1),
(211721, 12101, 772, '<td valign="top">This is a great shot for perspective and I''m giving it a 10.  The black and white along with the composition of this shot is excellent.  Your border is very distracting from your image.  Since the border color has nothing to do witht eh image and is not supported by any color in the image, it IS distracting.. be careful with that :) - setzler</td>', 'This is a great shot for perspective and I''m giving it a 10.  The black and white along with the composition of this shot is excellent.  Your border is very distracting from your image.  Since the border color has nothing to do witht eh image and is not supported by any color in the image, it IS distracting.. be careful with that :) - setzler', '2003-02-10 00:51:46.000000', NULL, 1),
(211744, 12101, 5318, '<td valign="top">very nice perspective soni  It''s gotta be a winner.I love the border</td>', 'very nice perspective soni  It''s gotta be a winner.I love the border', '2003-02-10 01:13:54.000000', NULL, 1),
(211774, 12285, 4628, '<td valign="top">The tip of the face looks a little out of focus. Perhaps a little wider depth of focus would have served well?</td>', 'The tip of the face looks a little out of focus. Perhaps a little wider depth of focus would have served well?', '2003-02-10 01:46:17.000000', NULL, 1),
(211824, 12299, 1143, '<td valign="top">I just can''t take any more Waldo pics so I''m coming over to the members challenge to treat myself. This is gorgeous. I think it''d look really pretty if you hand colored it and printed on watercolor paper. Gorgeous.</td>', 'I just can''t take any more Waldo pics so I''m coming over to the members challenge to treat myself. This is gorgeous. I think it''d look really pretty if you hand colored it and printed on watercolor paper. Gorgeous.', '2003-02-10 03:18:28.000000', NULL, 1),
(211826, 12084, 1143, '<td valign="top">COOOOL. The area where I used to live is just off to the right of this picture I think.  :(  I miss Boston.  Cool shot. Low enough to still make out everything.</td>', 'COOOOL. The area where I used to live is just off to the right of this picture I think.  :(  I miss Boston.  Cool shot. Low enough to still make out everything.', '2003-02-10 03:22:42.000000', NULL, 1),
(211827, 12118, 1143, '<td valign="top">I love the color of this shot. It''s just such a calming, pretty image. Beautiful use of perspective!</td>', 'I love the color of this shot. It''s just such a calming, pretty image. Beautiful use of perspective!', '2003-02-10 03:24:18.000000', NULL, 1),
