(213747, 12141, 772, '<td valign="top">very nice abstract :)  I really like your idea here... the lines and shapes become the subject of the photo, along with the contrasts... great shot :) - setzler</td>', 'very nice abstract :)  I really like your idea here... the lines and shapes become the subject of the photo, along with the contrasts... great shot :) - setzler', '2003-02-11 17:38:23.000000', NULL, 1),
(213749, 12101, 5044, '<td valign="top">I like this shot. The lines (baseboards and handrail) work well. I like the BW, nice tones, but not the border. Good DOF. The kids are really cute, especially the one at the end. She looks like she needs to go pee real bad.</td>', 'I like this shot. The lines (baseboards and handrail) work well. I like the BW, nice tones, but not the border. Good DOF. The kids are really cute, especially the one at the end. She looks like she needs to go pee real bad.', '2003-02-11 17:41:54.000000', NULL, 1),
(213752, 12306, 5044, '<td valign="top">I like this picture''s perspective so it matches the challenge well, but seems to me that the artifacts are a little too noticeable. Maybe too much USM or just a nasty side effect from the squares.</td>', 'I like this picture''s perspective so it matches the challenge well, but seems to me that the artifacts are a little too noticeable. Maybe too much USM or just a nasty side effect from the squares.', '2003-02-11 17:45:01.000000', NULL, 1),
(213753, 12130, 5044, '<td valign="top">Those are some baggy pants... Nice shot.</td>', 'Those are some baggy pants... Nice shot.', '2003-02-11 17:46:47.000000', NULL, 1),
(213756, 12307, 772, '<td valign="top">his is a beautiful photo.. the color and abstract ''perspective'' is excellent.. I had originally given this an 8 but i think it''s worth a 10 after absorbing it a little... great shot :) = 10 - setzler</td>', 'his is a beautiful photo.. the color and abstract ''perspective'' is excellent.. I had originally given this an 8 but i think it''s worth a 10 after absorbing it a little... great shot :) = 10 - setzler', '2003-02-11 17:49:36.000000', NULL, 1),
