(213777, 12176, 6696, '<td valign="top">Great contrast of subject matter between nature and man.  Also meets challenge well.  Nice job.<br/><br/><i>Message edited by author 2003-02-17 00:03:50.</i></td>', 'Great contrast of subject matter between nature and man.  Also meets challenge well.  Nice job.', '2003-02-11 18:09:55.000000', '2003-02-17 00:03:50.000000', 1),
