(214876, 12195, 6701, '<td valign="top">I really like this one.  Great lines, and shapes.  Plus the varied lighting is cool.  Nice show.</td>', 'I really like this one.  Great lines, and shapes.  Plus the varied lighting is cool.  Nice show.', '2003-02-13 16:00:08.000000', NULL, 1),
(214893, 12074, 772, '<td valign="top">The perspective in this shot is fairly interesting, but i think the overall subject matter may be a little weak overall.  There is no color or any specific element of the photo that really grabs my attention... - setzler</td>', 'The perspective in this shot is fairly interesting, but i think the overall subject matter may be a little weak overall.  There is no color or any specific element of the photo that really grabs my attention... - setzler', '2003-02-13 16:12:20.000000', NULL, 1),
