(216565, 12290, 1847, '<td valign="top">Beautiful colors.  I''m usually not a fan of the "all but one channel desaturated" pics, but it is so compartively subtle here that it works well.</td>', 'Beautiful colors.  I''m usually not a fan of the "all but one channel desaturated" pics, but it is so compartively subtle here that it works well.', '2003-02-16 23:46:12.000000', NULL, 1),
(216567, 12285, 1847, '<td valign="top">Exemplary use of a tight DOF.  Might have been nice to widen it just a touch to get that nose in focus, too.  But still a great shot.</td>', 'Exemplary use of a tight DOF.  Might have been nice to widen it just a touch to get that nose in focus, too.  But still a great shot.', '2003-02-16 23:47:02.000000', NULL, 1),
